    const width = 720, height = 240, left = 36, bottom = 218, plotWidth = width - 56, plotHeight = 190, x = index => left + (values.length < 2 ? plotWidth / 2 : index * plotWidth / (values.length - 1)), y = number => bottom - Math.max(0, number) / maximum * plotHeight;
    if (["line", "area", "stacked-area"].includes(currentChartType)) { const series = numericFields.slice(0, 6); let cumulative = values.map(() => 0); const shapes = series.map((field, seriesIndex) => { const previous = [...cumulative]; cumulative = cumulative.map((value, index) => value + Math.max(0, Number(values[index][field]) || 0)); const top = values.map((_, index) => `${x(index)},${y(currentChartType === "stacked-area" ? cumulative[index] : Number(values[index][field]) || 0)}`).join(" "); if (currentChartType === "line") return `<polyline points="${top}" fill="none" stroke="${colors[seriesIndex]}" stroke-width="3"/>`; const lower = values.map((_, index) => `${x(values.length - 1 - index)},${y(currentChartType === "stacked-area" ? previous[values.length - 1 - index] : 0)}`).join(" "); return `<polygon points="${top} ${lower}" fill="${colors[seriesIndex]}" fill-opacity="0.28" stroke="${colors[seriesIndex]}" stroke-width="2"/>`; }).join(""); content = `<svg viewBox="0 0 ${width} ${height}" aria-hidden="true"><line x1="${left}" y1="${bottom}" x2="${width - 20}" y2="${bottom}" stroke="currentColor" opacity=".35"/>${shapes}</svg><div class="insights-chart-legend">${series.map((field, index) => `<span><i style="background:${colors[index]}"></i>${escapeHtml(field)}</span>`).join("")}</div>`; }
