  renderHistory(); renderSaved(); document.querySelector("#insights-sample").addEventListener("change", event => { document.querySelector("#insights-editor").value = insightsSamples[event.target.value]; currentDefinitionId = undefined; document.querySelector('[data-action="save-query"]').textContent = "Save query"; });
